setup_replacements.old:
if string(workingContent) != headContent {
	// Working tree differs from HEAD — uncommitted changes
	result = append(result, relPath)
}

setup_replacements.new:
// Compare with line separators unified on both sides so that
// platform-dependent rewriting of text files at materialization
// time does not flag content that is already committed.
normalizedWorking := strings.ReplaceAll(string(workingContent), "\r\n", "\n")
normalizedHead := strings.ReplaceAll(headContent, "\r\n", "\n")
if normalizedWorking != normalizedHead {
	// Working tree differs from HEAD — uncommitted changes
	result = append(result, relPath)
}
